for r in "$@"; do echo "##### $r"; f=/workspace/research/runs/$r/stdout.log; [ -f "$f" ] && grep -E "LEAN_BUILT|BUILT|RECORD|CASE|PY_TWIN|Traceback|Error|==|REFUSED|decode: ok|orderViolation|rootLaid|inputsAt|callees|bodies|resolvable|walkBound|walkable|check:|count:|record-check:|probe|error" "$f" | awk '{ if (length($0) > 420) print substr($0,1,60) " ... " substr($0, length($0)-330); else print }'; done
